// AWS appelle cette fonction `handler` a chaque evenement.
// `event` contient les donnees de l'evenement declencheur.
export const handler = async (event) => {
  const nom = event.nom ?? 'monde'
  return {
    statusCode: 200,
    body: JSON.stringify({ message: `Bonjour ${nom}` }),
  }
}
